proof_attempts.proof:
intros R _ _ p q hp hq
constructor
(
  intro hq_eq_1;
  by_cases hp_eq_0 : p = 0;
  (exact hp_eq_0);
  (simp_all)
)
(
  intro hp_eq_0;
  have q_ne_zero : q ≠ 0 :=
  (
    intro hq0;
    rw [hq0] at hq;
    have h00 : (0 : R) ^ 0 = (0 : R) := hq.exp_char 0;
    rw [pow_zero] at h00;
    exact Nontrivial.zero_ne_one h00
  );
  have h_cast_inj : Function.Injective (Nat.cast : ℕ → R) := CharP.cast_injective_of_char_zero;
  have h2_pow_q_eq_2 : (2 : R) ^ q = (2 : R) := hq.exp_char 2;
  rw [Nat.cast_pow] at h2_pow_q_eq_2;
  apply h_cast_inj at h2_pow_q_eq_2;
  rcases (Nat.pow_eq_self_iff 2 q).mp h2_pow_q_eq_2 with h2_eq_0 | h2_eq_1 | hq_eq_1;
  case inl h2_eq_0 => exact Nat.noConfusion h2_eq_0;
  case inl h2_eq_1 => exact Nat.noConfusion h2_eq_1;
  case inr hq_eq_1 => exact hq_eq_1
)

